const WalletPage = () => {
  const { user } = useAuth();
  const [walletInfo, setWalletInfo] = useState(null);
  const [transactions, setTransactions] = useState([]);
  const [loading, setLoading] = useState(true);
  const [activeTab, setActiveTab] = useState('overview');
  const [depositAmount, setDepositAmount] = useState('');
  const [withdrawAmount, setWithdrawAmount] = useState('');
  const [showDepositForm, setShowDepositForm] = useState(false);
  const [showWithdrawForm, setShowWithdrawForm] = useState(false);

  // Fetch wallet info and transactions
  useEffect(() => {
    const fetchData = async () => {
      try {
        const [walletRes, transactionsRes] = await Promise.all([
          fetch(`${process.env.REACT_APP_API_URL || 'http://localhost:5000'}/api/wallet/balance/${user?.id}`, {
            headers: {
              'Authorization': `Bearer ${localStorage.getItem('token')}`
            }
          }),
          fetch(`${process.env.REACT_APP_API_URL || 'http://localhost:5000'}/api/wallet/transactions/${user?.id}`, {
            headers: {
              'Authorization': `Bearer ${localStorage.getItem('token')}`
            }
          })
        ]);

        const walletData = await walletRes.json();
        const transactionsData = await transactionsRes.json();

        setWalletInfo(walletData);
        setTransactions(transactionsData);
        setLoading(false);
      } catch (error) {
        console.error('Error fetching wallet data:', error);
        setLoading(false);
      }
    };

    if (user) {
      fetchData();
    }
  }, [user]);

  const handleDeposit = async () => {
    if (!depositAmount || parseFloat(depositAmount) <= 0) {
      alert('Please enter a valid amount');
      return;
    }

    try {
      const response = await fetch(`${process.env.REACT_APP_API_URL || 'http://localhost:5000'}/api/wallet/deposit`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${localStorage.getItem('token')}`
        },
        body: JSON.stringify({ 
          amount: parseFloat(depositAmount),
          method: 'credit_card' // Default method
        })
      });

      const data = await response.json();

      if (response.ok) {
        alert('Deposit successful!');
        setDepositAmount('');
        setShowDepositForm(false);
        // Refresh data
        window.location.reload();
      } else {
        alert(data.message || 'Deposit failed');
      }
    } catch (error) {
      console.error('Error processing deposit:', error);
      alert('Error processing deposit');
    }
  };

  const handleWithdraw = async () => {
    if (!withdrawAmount || parseFloat(withdrawAmount) <= 0) {
      alert('Please enter a valid amount');
      return;
    }

    if (parseFloat(withdrawAmount) > (walletInfo?.available || 0)) {
      alert('Insufficient balance');
      return;
    }

    try {
      const response = await fetch(`${process.env.REACT_APP_API_URL || 'http://localhost:5000'}/api/wallet/withdraw`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${localStorage.getItem('token')}`
        },
        body: JSON.stringify({ 
          amount: parseFloat(withdrawAmount),
          method: 'bank_transfer',
          destination: 'user_bank_account' // Placeholder
        })
      });

      const data = await response.json();

      if (response.ok) {
        alert('Withdrawal request submitted! It will be reviewed by an administrator.');
        setWithdrawAmount('');
        setShowWithdrawForm(false);
        // Refresh data
        window.location.reload();
      } else {
        alert(data.message || 'Withdrawal failed');
      }
    } catch (error) {
      console.error('Error processing withdrawal:', error);
      alert('Error processing withdrawal');
    }
  };

  if (loading) {
    return (
      <div className="loading-container">
        <div className="loading-spinner"></div>
        <p>Loading wallet...</p>
      </div>
    );
  }

  return (
    <div className="wallet-page">
      <div className="page-header">
        <h1>Wallet</h1>
      </div>

      <div className="wallet-tabs">
        <button 
          className={`tab-button ${activeTab === 'overview' ? 'active' : ''}`}
          onClick={() => setActiveTab('overview')}
        >
          Overview
        </button>
        <button 
          className={`tab-button ${activeTab === 'transactions' ? 'active' : ''}`}
          onClick={() => setActiveTab('transactions')}
        >
          Transactions
        </button>
        <button 
          className={`tab-button ${activeTab === 'deposit' ? 'active' : ''}`}
          onClick={() => setActiveTab('deposit')}
        >
          Deposit
        </button>
        <button 
          className={`tab-button ${activeTab === 'withdraw' ? 'active' : ''}`}
          onClick={() => setActiveTab('withdraw')}
        >
          Withdraw
        </button>
      </div>

      <div className="tab-content">
        {activeTab === 'overview' && (
          <div className="wallet-overview">
            <div className="wallet-balances">
              <div className="balance-card">
                <h3>Available</h3>
                <div className="balance-amount available">
                  {walletInfo?.available?.toLocaleString() || '0'} <span className="ampcoin">AMP</span>
                </div>
              </div>
              <div className="balance-card">
                <h3>Locked</h3>
                <div className="balance-amount locked">
                  {walletInfo?.locked?.toLocaleString() || '0'} <span className="ampcoin">AMP</span>
                </div>
              </div>
              <div className="balance-card">
                <h3>Total</h3>
                <div className="balance-amount total">
                  {walletInfo?.total?.toLocaleString() || '0'} <span className="ampcoin">AMP</span>
                </div>
              </div>
            </div>

            <div className="wallet-actions">
              <button 
                className="btn btn-primary btn-lg"
                onClick={() => setShowDepositForm(true)}
              >
                Deposit
              </button>
              <button 
                className="btn btn-secondary btn-lg"
                onClick={() => setShowWithdrawForm(true)}
                disabled={walletInfo?.available <= 0}
              >
                Withdraw
              </button>
            </div>
          </div>
        )}

        {activeTab === 'transactions' && (
          <div className="transactions-list">
            <h3>Recent Transactions</h3>
            {transactions.length === 0 ? (
              <p>No transactions found.</p>
            ) : (
              <table className="table">
                <thead>
                  <tr>
                    <th>Type</th>
                    <th>Amount</th>
                    <th>Status</th>
                    <th>Date</th>
                    <th>Details</th>
                  </tr>
                </thead>
                <tbody>
                  {transactions.map((transaction, index) => (
                    <tr key={index}>
                      <td>
                        <span className={`transaction-type ${transaction.type}`}>
                          {transaction.type.replace('_', ' ').toUpperCase()}
                        </span>
                      </td>
                      <td>
                        <span className={transaction.amount >= 0 ? 'positive' : 'negative'}>
                          {transaction.amount >= 0 ? '+' : ''}
                          {transaction.amount?.toLocaleString() || '0'} AMP
                        </span>
                      </td>
                      <td>
                        <span className={`status-badge ${transaction.status}`}>
                          {transaction.status.toUpperCase()}
                        </span>
                      </td>
                      <td>
                        {new Date(transaction.timestamp).toLocaleString()}
                      </td>
                      <td>
                        {transaction.metadata?.note || transaction.type}
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            )}
          </div>
        )}

        {activeTab === 'deposit' && (
          <div className="deposit-section">
            <h3>Deposit Funds</h3>
            {!showDepositForm ? (
              <div className="deposit-options">
                <button 
                  className="btn btn-primary btn-lg"
                  onClick={() => setShowDepositForm(true)}
                >
                  Make Deposit
                </button>
              </div>
            ) : (
              <div className="deposit-form">
                <div className="form-group">
                  <label className="form-label">Amount (AMP)</label>
                  <input
                    type="number"
                    value={depositAmount}
                    onChange={(e) => setDepositAmount(e.target.value)}
                    className="form-control"
                    placeholder="Enter amount"
                    min="10"
                  />
                </div>
                <div className="form-group">
                  <label className="form-label">Payment Method</label>
                  <select className="form-control">
                    <option value="credit_card">Credit Card</option>
                    <option value="paypal">PayPal</option>
                    <option value="bank_transfer">Bank Transfer</option>
                  </select>
                </div>
                <div className="form-actions">
                  <button 
                    className="btn btn-secondary" 
                    onClick={() => setShowDepositForm(false)}
                  >
                    Cancel
                  </button>
                  <button 
                    className="btn btn-primary" 
                    onClick={handleDeposit}
                  >
                    Process Deposit
                  </button>
                </div>
              </div>
            )}
          </div>
        )}

        {activeTab === 'withdraw' && (
          <div className="withdraw-section">
            <h3>Withdraw Funds</h3>
            {!showWithdrawForm ? (
              <div className="withdraw-options">
                <button 
                  className="btn btn-secondary btn-lg"
                  onClick={() => setShowWithdrawForm(true)}
                  disabled={walletInfo?.available <= 0}
                >
                  Make Withdrawal
                </button>
              </div>
            ) : (
              <div className="withdraw-form">
                <div className="form-group">
                  <label className="form-label">Amount (AMP)</label>
                  <input
                    type="number"
                    value={withdrawAmount}
                    onChange={(e) => setWithdrawAmount(e.target.value)}
                    className="form-control"
                    placeholder="Enter amount"
                    min="10"
                    max={walletInfo?.available || 0}
                  />
                </div>
                <div className="form-group">
                  <label className="form-label">Destination</label>
                  <input
                    type="text"
                    className="form-control"
                    placeholder="Enter bank account or wallet address"
                  />
                </div>
                <div className="form-actions">
                  <button 
                    className="btn btn-secondary" 
                    onClick={() => setShowWithdrawForm(false)}
                  >
                    Cancel
                  </button>
                  <button 
                    className="btn btn-danger" 
                    onClick={handleWithdraw}
                  >
                    Submit Withdrawal
                  </button>
                </div>
              </div>
            )}
          </div>
        )}
      </div>
    </div>
  );
};

export default WalletPage;
